CREATE OR REPLACE FUNCTION public.montra_market_secrets() RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path TO '' AS $$select coalesce(jsonb_object_agg(name,decrypted_secret),'{}'::jsonb) from vault.decrypted_secrets where name in ('montra_job_token','montra_gold_egypt_key','montra_twelvedata_key','montra_exchangerate_key')$$; REVOKE ALL ON FUNCTION public.montra_market_secrets() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.montra_market_secrets() TO service_role;